#!/usr/bin/env node
import {
  findProjectRoot
} from "./chunk-IWNALT6P.js";
import {
  GramConfigFileSchema
} from "./chunk-5APUWLPI.js";
import {
  GramConfigError
} from "./chunk-IXNX2GX7.js";

// src/core/config.ts
import { readFile } from "fs/promises";
import { homedir } from "os";
import { join } from "path";
import { parse } from "yaml";
import { defu } from "defu";
import { z } from "zod";
async function readYaml(path) {
  try {
    const content = await readFile(path, "utf-8");
    return parse(content) ?? {};
  } catch {
    return {};
  }
}
function mergeConfigLayers(project, global) {
  const merged = defu(project, global);
  if (project.ai?.provider && global.ai?.provider !== project.ai.provider) {
    merged.ai = { ...project.ai };
  }
  return merged;
}
async function loadConfig() {
  const projectRoot = await findProjectRoot();
  const global = await readYaml(
    join(homedir(), ".config", "gram", "config.yaml")
  );
  const project = await readYaml(join(projectRoot, ".gram", "config.yaml"));
  const result = GramConfigFileSchema.safeParse(
    mergeConfigLayers(project, global)
  );
  if (!result.success) {
    throw new GramConfigError(
      `Invalid configuration in .gram/config.yaml or ~/.config/gram/config.yaml:
${z.prettifyError(result.error)}`
    );
  }
  const config = result.data;
  config.projectRoot = projectRoot;
  return config;
}

export {
  loadConfig
};
